import type { TimberLogEntry } from './types.js';

/** Shallow JSON clone — same as BEFORE `utils/object.clone` (filter arrays must not mutate in-flight). */
export const clone = <T>(value: T): T => {
    if (value === undefined) {
        return undefined as T;
    }

    return JSON.parse(JSON.stringify(value)) as T;
};

/** Retain directories so recursive and event-added logs remain distinguishable. */
export const getPrettyPathText = (value: string | null | undefined, logDirectory?: string): string => {
    if (!value) {
        return '';
    }

    const path = value.replace(/\\/g, '/');
    const root = logDirectory?.replace(/\\/g, '/').replace(/\/$/, '');

    return root && path.startsWith(`${root}/`) ? `@storage/logs/${path.slice(root.length + 1)}` : path;
};

export const getPrettyPathHtml = (value: string | null | undefined, logDirectory?: string): string => {
    const text = getPrettyPathText(value, logDirectory);
    const split = text.lastIndexOf('/') + 1;

    return text ? `<span>${escapeHtml(text.slice(0, split))}</span>${escapeHtml(text.slice(split))}` : '';
};

export const getPrettySize = (bytes: number | null | undefined, decimals = 2): string => {
    if (!bytes) {
        return '';
    }

    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(decimals))} ${sizes[i]}`;
};

/**
 * Stable expand key — BEFORE: `[datetime, level, channel, category, message.slice(0,200)].join(':')`
 * with newlines stripped.
 */
export const getLogId = (log: TimberLogEntry): string => {
    return [log.datetime, log.level, log.channel, log.category, (log.message || '').slice(0, 200)]
        .join(':')
        .replace(/(\r\n|\n|\r)/gm, '');
};

export const formatLevelLabel = (level: string | null | undefined, toLowerCase = false): string => {
    if (!level) {
        return '';
    }

    if (toLowerCase) {
        return level.toLowerCase();
    }

    return level.charAt(0).toUpperCase() + level.slice(1).toLowerCase();
};

/** Wrap literal search hits in `<mark>` without treating user input as a regular expression. */
export const markSearchHits = (message: string, searchText: string): string => {
    if (!searchText) {
        return message;
    }

    // Undo exactly the entities emitted by PHP's htmlspecialchars, then escape each
    // output segment. Matching inside an encoded entity corrupts the visible message.
    const entities: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', '#039': "'" };
    const text = message.replace(/&(amp|lt|gt|quot|#039);/g, (_, name: string) => entities[name]);
    const escapedSearch = searchText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    let result = '';
    let offset = 0;

    for (const match of text.matchAll(new RegExp(escapedSearch, 'gi'))) {
        result += escapeHtml(text.slice(offset, match.index));
        result += `<mark>${escapeHtml(match[0])}</mark>`;
        offset = match.index + match[0].length;
    }

    return result + escapeHtml(text.slice(offset));
};

export const escapeHtml = (value: string): string => {
    return value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
};

export const formatNumber = (number: number | null | undefined, decimals?: number): string => {
    return Craft.formatNumber(number ?? 0, decimals);
};
